            $st->bind_param('isssdissisis',$cliente,$titulo,$descripcion,$estado,$importe,$equipos,$fecha,$prox,$usuario['id'],$usuario['nombre'],$responsable['id'],$responsable['nombre']); $st->execute(); $st->close();
