            $permitidos=array('DETECTADA','COTIZANDO','ESPERANDO_RESPUESTA','PROBABLE','GANADA','PERDIDA'); if(!in_array($estado,$permitidos,true))throw new RuntimeException('Estado inválido.');
            $st=$conexion->prepare("UPDATE comercial_oportunidades SET estado=? WHERE oportunidad_id=?"); $st->bind_param('si',$estado,$id); $st->execute(); $st->close();
