            $st=$conexion->prepare("INSERT INTO clientes_especificaciones_tecnicas(cliente_id,tipo,categoria,titulo,detalle,usuario_id,usuario_nombre) VALUES(?,?,?,?,?,?,?)");
            $st->bind_param('issssis',$cliente,$tipo,$categoria,$titulo,$detalle,$usuario['id'],$usuario['nombre']);$st->execute();$st->close();
