            $id=(int)($_POST['especificacion_id']??0);$cliente=(int)($_POST['cliente_id']??0);$activo=strtoupper(trim((string)($_POST['activo']??'NO')))==='SI'?'SI':'NO';
            if($id<=0||$cliente<=0)throw new RuntimeException('Especificación técnica inválida.');
            $st=$conexion->prepare("UPDATE clientes_especificaciones_tecnicas SET activo=? WHERE especificacion_id=? AND cliente_id=?");$st->bind_param('sii',$activo,$id,$cliente);$st->execute();$st->close();
