/* v429 - período anterior equivalente para comparar desempeño sin mezclar ventanas. */
$desdeObj=DateTimeImmutable::createFromFormat('!Y-m-d',$desde)?:new DateTimeImmutable('first day of January');
$hastaObj=DateTimeImmutable::createFromFormat('!Y-m-d',$hasta)?:new DateTimeImmutable('today');
if($hastaObj<$desdeObj){$tmp=$desdeObj;$desdeObj=$hastaObj;$hastaObj=$tmp;}
$diasPeriodo=(int)$desdeObj->diff($hastaObj)->days+1;
$hastaAnterior=$desdeObj->modify('-1 day');
$desdeAnterior=$hastaAnterior->modify('-'.max(0,$diasPeriodo-1).' days');
$desdeAnteriorSql=$desdeAnterior->format('Y-m-d').' 00:00:00';
$hastaAnteriorSql=$hastaAnterior->format('Y-m-d').' 23:59:59';
