$qCliente=trim((string)($_GET['q_cliente']??''));
$clientesBusquedaFicha=array();
if($qCliente!==''){
    $qNorm=mb_strtolower($qCliente,'UTF-8');
    foreach($clientes as $c){
        $texto=mb_strtolower(implode(' ',array($c['clientes_codigo']??'',$c['clientes_nomfantasia']??'',$c['clientes_razonsocial']??'',$c['clientes_contacto']??'',$c['clientes_emails']??'')),'UTF-8');
        if(mb_strpos($texto,$qNorm)!==false)$clientesBusquedaFicha[]=$c;
        if(count($clientesBusquedaFicha)>=40)break;
    }
}


function consultaUna(mysqli $c,string $sql,array $params=array(),string $types=''): array{
    if(!$params){$r=$c->query($sql);return $r?($r->fetch_assoc()?:array()):array();}
    $st=$c->prepare($sql); if(!$st)return array(); $st->bind_param($types,...$params); $st->execute(); $x=$st->get_result()->fetch_assoc()?:array(); $st->close(); return $x;
}
function consultaVarias(mysqli $c,string $sql,array $params=array(),string $types=''): array{
    $out=array(); if(!$params){$r=$c->query($sql);if($r)while($x=$r->fetch_assoc())$out[]=$x;return $out;}
    $st=$c->prepare($sql); if(!$st)return $out; $st->bind_param($types,...$params); $st->execute(); $r=$st->get_result(); while($x=$r->fetch_assoc())$out[]=$x; $st->close(); return $out;
}

/* v427 - KPIs por cohorte: una conversión nace de la cotización del período,
 * aunque el pedido se confirme posteriormente. Los pedidos DIRECTOS no inflan la tasa. */
$kpiCot=consultaUna($conexion,"SELECT COUNT(*) cantidad,COALESCE(SUM(total),0) total FROM cotizaciones WHERE cotizacion_numero IS NOT NULL AND estado<>'ANULADA' AND fecha_creacion BETWEEN ? AND ?",array($desdeSql,$hastaSql),'ss');
$kpiPed=consultaUna($conexion,"SELECT COUNT(*) cantidad,COALESCE(SUM(total),0) total FROM pedidos WHERE pedido_numero IS NOT NULL AND estado<>'ANULADO' AND fecha_creacion BETWEEN ? AND ?",array($desdeSql,$hastaSql),'ss');
$kpiCohorte=consultaUna($conexion,"SELECT COUNT(*) cotizaciones,COALESCE(SUM(c.total),0) importe_cotizado,SUM(CASE WHEN p.pedido_id IS NOT NULL THEN 1 ELSE 0 END) convertidas,COALESCE(SUM(CASE WHEN p.pedido_id IS NOT NULL THEN p.total ELSE 0 END),0) importe_convertido,AVG(CASE WHEN p.pedido_id IS NOT NULL THEN DATEDIFF(p.fecha_creacion,c.fecha_creacion) END) dias_promedio FROM cotizaciones c LEFT JOIN pedidos p ON p.cotizacion_id=c.cotizacion_id AND p.estado<>'ANULADO' WHERE c.cotizacion_numero IS NOT NULL AND c.estado<>'ANULADA' AND c.fecha_creacion BETWEEN ? AND ?",array($desdeSql,$hastaSql),'ss');
$kpiCohorteC=consultaUna($conexion,"SELECT COUNT(*) cotizaciones,SUM(CASE WHEN p.pedido_id IS NOT NULL AND p.pedido_tipo='OBRA' THEN 1 ELSE 0 END) convertidas FROM cotizaciones c LEFT JOIN pedidos p ON p.cotizacion_id=c.cotizacion_id AND p.estado<>'ANULADO' WHERE c.cotizacion_tipo='CONTROL' AND c.cotizacion_numero IS NOT NULL AND c.estado<>'ANULADA' AND c.fecha_creacion BETWEEN ? AND ?",array($desdeSql,$hastaSql),'ss');
$kpiCohorteR=consultaUna($conexion,"SELECT COUNT(*) cotizaciones,SUM(CASE WHEN p.pedido_id IS NOT NULL AND p.pedido_tipo='SUMINISTROS' THEN 1 ELSE 0 END) convertidas FROM cotizaciones c LEFT JOIN pedidos p ON p.cotizacion_id=c.cotizacion_id AND p.estado<>'ANULADO' WHERE c.cotizacion_tipo='SUMINISTROS' AND c.cotizacion_numero IS NOT NULL AND c.estado<>'ANULADA' AND c.fecha_creacion BETWEEN ? AND ?",array($desdeSql,$hastaSql),'ss');
$kpiDirectos=consultaUna($conexion,"SELECT SUM(CASE WHEN pedido_tipo='OBRA' THEN 1 ELSE 0 END) obras,SUM(CASE WHEN pedido_tipo='SUMINISTROS' THEN 1 ELSE 0 END) suministros,COUNT(*) total FROM pedidos WHERE origen='DIRECTO' AND pedido_numero IS NOT NULL AND estado<>'ANULADO' AND fecha_creacion BETWEEN ? AND ?",array($desdeSql,$hastaSql),'ss');
$diasConversion=consultaVarias($conexion,"SELECT DATEDIFF(p.fecha_creacion,c.fecha_creacion) dias FROM cotizaciones c JOIN pedidos p ON p.cotizacion_id=c.cotizacion_id AND p.estado<>'ANULADO' WHERE c.cotizacion_numero IS NOT NULL AND c.estado<>'ANULADA' AND c.fecha_creacion BETWEEN ? AND ? ORDER BY dias",array($desdeSql,$hastaSql),'ss');
$diasValores=array_map(function($r){ return (int)$r['dias']; },$diasConversion); $medianaConversion=0.0; if($diasValores){$n=count($diasValores);$m=intdiv($n,2);$medianaConversion=$n%2?$diasValores[$m]:(($diasValores[$m-1]+$diasValores[$m])/2);}
$conversion=((int)($kpiCohorte['cotizaciones']??0)>0)?((int)($kpiCohorte['convertidas']??0)/(int)$kpiCohorte['cotizaciones']*100):0;
$conversionC=((int)($kpiCohorteC['cotizaciones']??0)>0)?((int)($kpiCohorteC['convertidas']??0)/(int)$kpiCohorteC['cotizaciones']*100):0;
$conversionR=((int)($kpiCohorteR['cotizaciones']??0)>0)?((int)($kpiCohorteR['convertidas']??0)/(int)$kpiCohorteR['cotizaciones']*100):0;
$ticketPedido=((int)($kpiPed['cantidad']??0)>0)?((float)($kpiPed['total']??0)/(int)$kpiPed['cantidad']):0;

/* v429 - comparación contra una ventana inmediatamente anterior de igual duración. */
$kpiCotAnterior=consultaUna($conexion,"SELECT COUNT(*) cantidad,COALESCE(SUM(total),0) total FROM cotizaciones WHERE cotizacion_numero IS NOT NULL AND estado<>'ANULADA' AND fecha_creacion BETWEEN ? AND ?",array($desdeAnteriorSql,$hastaAnteriorSql),'ss');
$kpiPedAnterior=consultaUna($conexion,"SELECT COUNT(*) cantidad,COALESCE(SUM(total),0) total FROM pedidos WHERE pedido_numero IS NOT NULL AND estado<>'ANULADO' AND fecha_creacion BETWEEN ? AND ?",array($desdeAnteriorSql,$hastaAnteriorSql),'ss');
$kpiCohorteAnterior=consultaUna($conexion,"SELECT COUNT(*) cotizaciones,COALESCE(SUM(c.total),0) importe_cotizado,SUM(CASE WHEN EXISTS(SELECT 1 FROM pedidos p WHERE p.cotizacion_id=c.cotizacion_id AND p.estado<>'ANULADO') THEN 1 ELSE 0 END) convertidas FROM cotizaciones c WHERE c.cotizacion_numero IS NOT NULL AND c.estado<>'ANULADA' AND c.fecha_creacion BETWEEN ? AND ?",array($desdeAnteriorSql,$hastaAnteriorSql),'ss');
$conversionAnterior=((int)($kpiCohorteAnterior['cotizaciones']??0)>0)?((int)($kpiCohorteAnterior['convertidas']??0)/(int)$kpiCohorteAnterior['cotizaciones']*100):0;
$ticketPedidoAnterior=((int)($kpiPedAnterior['cantidad']??0)>0)?((float)($kpiPedAnterior['total']??0)/(int)$kpiPedAnterior['cantidad']):0;
$deltaConversion=$conversion-$conversionAnterior;
$deltaCotizaciones=(int)($kpiCot['cantidad']??0)-(int)($kpiCotAnterior['cantidad']??0);
$deltaPedidos=(int)($kpiPed['cantidad']??0)-(int)($kpiPedAnterior['cantidad']??0);
$deltaImportePedidos=(float)($kpiPed['total']??0)-(float)($kpiPedAnterior['total']??0);
$deltaTicket=$ticketPedido-$ticketPedidoAnterior;
$equiposPeriodo=consultaUna($conexion,"SELECT COALESCE(SUM(d.cantidad),0) equipos FROM pedidos p JOIN pedidos_detalle d ON d.pedido_id=p.pedido_id WHERE p.estado<>'ANULADO' AND p.fecha_creacion BETWEEN ? AND ? AND d.modulo='CONTROL' AND d.concepto='Base'",array($desdeSql,$hastaSql),'ss');
$whereResp=$responsableIdFiltro>0?' AND responsable_id='.(int)$responsableIdFiltro:'';
$oportunidadesAbiertas=consultaUna($conexion,"SELECT COUNT(*) cantidad,COALESCE(SUM(importe_estimado),0) importe FROM comercial_oportunidades WHERE estado NOT IN('GANADA','PERDIDA')".$whereResp);
$probabilidades=array('DETECTADA'=>parametroComercial($conexion,'PIPELINE_DETECTADA',10),'COTIZANDO'=>parametroComercial($conexion,'PIPELINE_COTIZANDO',30),'ESPERANDO_RESPUESTA'=>parametroComercial($conexion,'PIPELINE_ESPERANDO_RESPUESTA',50),'PROBABLE'=>parametroComercial($conexion,'PIPELINE_PROBABLE',75));
$pipelineFilas=consultaVarias($conexion,"SELECT estado,COALESCE(SUM(importe_estimado),0) importe FROM comercial_oportunidades WHERE estado NOT IN('GANADA','PERDIDA')".$whereResp." GROUP BY estado");
$pipelinePonderado=0.0; foreach($pipelineFilas as $pf){$pipelinePonderado+=(float)$pf['importe']*((float)($probabilidades[$pf['estado']]??0)/100);}
$pendientesHoy=consultaUna($conexion,"SELECT (SELECT COUNT(*) FROM comercial_seguimientos WHERE estado='PENDIENTE' AND proximo_contacto IS NOT NULL AND proximo_contacto<=NOW()".$whereResp.")+(SELECT COUNT(*) FROM comercial_oportunidades WHERE estado NOT IN('GANADA','PERDIDA') AND proximo_contacto IS NOT NULL AND proximo_contacto<=NOW()".$whereResp.") cantidad");

$seguimientosPendientes=consultaVarias($conexion,"SELECT s.*,c.clientes_nomfantasia,c.clientes_codigo FROM comercial_seguimientos s JOIN clientes c ON c.clientes_id=s.cliente_id WHERE s.estado='PENDIENTE'".$whereResp." ORDER BY CASE WHEN s.proximo_contacto IS NULL THEN 1 ELSE 0 END,s.proximo_contacto ASC,s.fecha_creacion DESC LIMIT 80");
$oportunidades=consultaVarias($conexion,"SELECT o.*,c.clientes_nomfantasia,c.clientes_codigo FROM comercial_oportunidades o JOIN clientes c ON c.clientes_id=o.cliente_id WHERE 1=1".$whereResp." ORDER BY FIELD(o.estado,'PROBABLE','ESPERANDO_RESPUESTA','COTIZANDO','DETECTADA','GANADA','PERDIDA'),o.proximo_contacto IS NULL,o.proximo_contacto ASC,o.fecha_estimada IS NULL,o.fecha_estimada ASC,o.fecha_creacion DESC LIMIT 120");
$agendaHoy=consultaVarias($conexion,"SELECT 'SEGUIMIENTO' origen,s.seguimiento_id id,s.cliente_id,s.tipo titulo,s.nota detalle,s.proximo_contacto,s.responsable_nombre,c.clientes_nomfantasia,c.clientes_codigo FROM comercial_seguimientos s JOIN clientes c ON c.clientes_id=s.cliente_id WHERE s.estado='PENDIENTE' AND s.proximo_contacto IS NOT NULL AND DATE(s.proximo_contacto)=CURDATE()".$whereResp." UNION ALL SELECT 'OPORTUNIDAD',o.oportunidad_id,o.cliente_id,o.titulo,o.descripcion,o.proximo_contacto,o.responsable_nombre,c.clientes_nomfantasia,c.clientes_codigo FROM comercial_oportunidades o JOIN clientes c ON c.clientes_id=o.cliente_id WHERE o.estado NOT IN('GANADA','PERDIDA') AND o.proximo_contacto IS NOT NULL AND DATE(o.proximo_contacto)=CURDATE()".$whereResp." ORDER BY proximo_contacto LIMIT 80");
$agendaVencida=consultaVarias($conexion,"SELECT 'SEGUIMIENTO' origen,s.seguimiento_id id,s.cliente_id,s.tipo titulo,s.nota detalle,s.proximo_contacto,s.responsable_nombre,c.clientes_nomfantasia,c.clientes_codigo FROM comercial_seguimientos s JOIN clientes c ON c.clientes_id=s.cliente_id WHERE s.estado='PENDIENTE' AND s.proximo_contacto<NOW() AND DATE(s.proximo_contacto)<CURDATE()".$whereResp." UNION ALL SELECT 'OPORTUNIDAD',o.oportunidad_id,o.cliente_id,o.titulo,o.descripcion,o.proximo_contacto,o.responsable_nombre,c.clientes_nomfantasia,c.clientes_codigo FROM comercial_oportunidades o JOIN clientes c ON c.clientes_id=o.cliente_id WHERE o.estado NOT IN('GANADA','PERDIDA') AND o.proximo_contacto<NOW() AND DATE(o.proximo_contacto)<CURDATE()".$whereResp." ORDER BY proximo_contacto LIMIT 80");
$agendaProxima=consultaVarias($conexion,"SELECT 'SEGUIMIENTO' origen,s.seguimiento_id id,s.cliente_id,s.tipo titulo,s.nota detalle,s.proximo_contacto,s.responsable_nombre,c.clientes_nomfantasia,c.clientes_codigo FROM comercial_seguimientos s JOIN clientes c ON c.clientes_id=s.cliente_id WHERE s.estado='PENDIENTE' AND s.proximo_contacto>NOW() AND s.proximo_contacto<=DATE_ADD(NOW(),INTERVAL 7 DAY)".$whereResp." UNION ALL SELECT 'OPORTUNIDAD',o.oportunidad_id,o.cliente_id,o.titulo,o.descripcion,o.proximo_contacto,o.responsable_nombre,c.clientes_nomfantasia,c.clientes_codigo FROM comercial_oportunidades o JOIN clientes c ON c.clientes_id=o.cliente_id WHERE o.estado NOT IN('GANADA','PERDIDA') AND o.proximo_contacto>NOW() AND o.proximo_contacto<=DATE_ADD(NOW(),INTERVAL 7 DAY)".$whereResp." ORDER BY proximo_contacto LIMIT 80");

$ranking=consultaVarias($conexion,"SELECT c.clientes_id,c.clientes_codigo,c.clientes_nomfantasia,
 COALESCE(co.cotizaciones,0) cotizaciones,COALESCE(co.convertidas,0) convertidas,
 COALESCE(co.importe_cotizado,0) importe_cotizado,COALESCE(co.importe_convertido,0) importe_convertido,
 COALESCE(pe.pedidos,0) pedidos,COALESCE(eq.equipos,0) equipos,
 COALESCE(pe.total_pedidos,0) total_pedidos,pe.ultimo_pedido
 FROM clientes c
 LEFT JOIN (
   SELECT c0.cliente_id,COUNT(*) cotizaciones,
          SUM(CASE WHEN EXISTS(SELECT 1 FROM pedidos px WHERE px.cotizacion_id=c0.cotizacion_id AND px.estado<>'ANULADO') THEN 1 ELSE 0 END) convertidas,
          COALESCE(SUM(c0.total),0) importe_cotizado,
          COALESCE(SUM(CASE WHEN EXISTS(SELECT 1 FROM pedidos py WHERE py.cotizacion_id=c0.cotizacion_id AND py.estado<>'ANULADO') THEN c0.total ELSE 0 END),0) importe_convertido
   FROM cotizaciones c0
   WHERE c0.cotizacion_numero IS NOT NULL AND c0.estado<>'ANULADA' AND c0.fecha_creacion BETWEEN ? AND ?
   GROUP BY c0.cliente_id
 ) co ON co.cliente_id=c.clientes_id
 LEFT JOIN (SELECT cliente_id,COUNT(*) pedidos,SUM(total) total_pedidos,MAX(fecha_creacion) ultimo_pedido FROM pedidos WHERE pedido_numero IS NOT NULL AND estado<>'ANULADO' AND fecha_creacion BETWEEN ? AND ? GROUP BY cliente_id) pe ON pe.cliente_id=c.clientes_id
 LEFT JOIN (SELECT p.cliente_id,SUM(d.cantidad) equipos FROM pedidos p JOIN pedidos_detalle d ON d.pedido_id=p.pedido_id WHERE p.pedido_numero IS NOT NULL AND p.estado<>'ANULADO' AND p.fecha_creacion BETWEEN ? AND ? AND d.modulo='CONTROL' AND d.concepto='Base' GROUP BY p.cliente_id) eq ON eq.cliente_id=c.clientes_id
 WHERE c.clientes_habilitado='SI' AND (COALESCE(co.cotizaciones,0)>0 OR COALESCE(pe.pedidos,0)>0)
 ORDER BY equipos DESC,convertidas DESC,pedidos DESC,c.clientes_nomfantasia LIMIT 100",array($desdeSql,$hastaSql,$desdeSql,$hastaSql,$desdeSql,$hastaSql),'ssssss');

$clientesInactivos=consultaVarias($conexion,"SELECT c.clientes_id,c.clientes_codigo,c.clientes_nomfantasia,MAX(p.fecha_creacion) ultimo_pedido,DATEDIFF(CURDATE(),DATE(MAX(p.fecha_creacion))) dias
 FROM clientes c LEFT JOIN pedidos p ON p.cliente_id=c.clientes_id AND p.estado<>'ANULADO'
 WHERE c.clientes_habilitado='SI' GROUP BY c.clientes_id,c.clientes_codigo,c.clientes_nomfantasia
 HAVING ultimo_pedido IS NOT NULL AND dias>=90 ORDER BY dias DESC LIMIT 80");

// Productos por mes: se extraen de la descripción técnica real guardada en detalle.
$controlesRows=consultaVarias($conexion,"SELECT DATE_FORMAT(p.fecha_creacion,'%Y-%m') mes,d.descripcion,d.cantidad FROM pedidos p JOIN pedidos_detalle d ON d.pedido_id=p.pedido_id WHERE p.estado<>'ANULADO' AND p.fecha_creacion BETWEEN ? AND ? AND d.modulo='CONTROL' AND d.concepto='Base'",array($desdeSql,$hastaSql),'ss');
$controlesMes=array(); foreach($controlesRows as $x){$m=$x['mes'];$modelo=comercialExtraerModeloControl((string)$x['descripcion']);$controlesMes[$m][$modelo]=($controlesMes[$m][$modelo]??0)+(float)$x['cantidad'];}
$pulsRows=consultaVarias($conexion,"SELECT DATE_FORMAT(p.fecha_creacion,'%Y-%m') mes,d.descripcion,d.cantidad FROM pedidos p JOIN pedidos_detalle d ON d.pedido_id=p.pedido_id WHERE p.estado<>'ANULADO' AND p.fecha_creacion BETWEEN ? AND ? AND d.modulo='SENALIZACION' AND (d.concepto LIKE '%Botonera%' OR d.concepto LIKE '%Pulsador%')",array($desdeSql,$hastaSql),'ss');
$pulsMes=array(); foreach($pulsRows as $x){$m=$x['mes'];$modelo=comercialExtraerModeloPulsador((string)$x['descripcion']);$pulsMes[$m][$modelo]=($pulsMes[$m][$modelo]??0)+(float)$x['cantidad'];}
ksort($controlesMes);ksort($pulsMes);

// Tendencia de pedidos por mes.
$tendencia=consultaVarias($conexion,"SELECT DATE_FORMAT(fecha_creacion,'%Y-%m') mes,COUNT(*) pedidos,COALESCE(SUM(total),0) importe FROM pedidos WHERE estado<>'ANULADO' AND fecha_creacion>=DATE_SUB(CURDATE(),INTERVAL 12 MONTH) GROUP BY DATE_FORMAT(fecha_creacion,'%Y-%m') ORDER BY mes");
$maxTend=1; foreach($tendencia as $x)$maxTend=max($maxTend,(int)$x['pedidos']);

$crecimiento=consultaVarias($conexion,"SELECT c.clientes_id,c.clientes_codigo,c.clientes_nomfantasia,COALESCE(a.actual,0) actual,COALESCE(b.anterior,0) anterior FROM clientes c LEFT JOIN (SELECT cliente_id,COUNT(*) actual FROM pedidos WHERE estado<>'ANULADO' AND fecha_creacion>=DATE_SUB(CURDATE(),INTERVAL 6 MONTH) GROUP BY cliente_id) a ON a.cliente_id=c.clientes_id LEFT JOIN (SELECT cliente_id,COUNT(*) anterior FROM pedidos WHERE estado<>'ANULADO' AND fecha_creacion>=DATE_SUB(CURDATE(),INTERVAL 12 MONTH) AND fecha_creacion<DATE_SUB(CURDATE(),INTERVAL 6 MONTH) GROUP BY cliente_id) b ON b.cliente_id=c.clientes_id WHERE COALESCE(a.actual,0)>0 OR COALESCE(b.anterior,0)>0 ORDER BY (COALESCE(a.actual,0)-COALESCE(b.anterior,0)) DESC,c.clientes_nomfantasia LIMIT 100");
$topAccesorios=consultaVarias($conexion,"SELECT COALESCE(NULLIF(d.descripcion,''),NULLIF(d.concepto,''),d.codigo) item,SUM(d.cantidad) cantidad FROM pedidos p JOIN pedidos_detalle d ON d.pedido_id=p.pedido_id WHERE p.estado<>'ANULADO' AND p.fecha_creacion BETWEEN ? AND ? AND d.modulo='ACCESORIOS' GROUP BY COALESCE(NULLIF(d.descripcion,''),NULLIF(d.concepto,''),d.codigo) ORDER BY cantidad DESC LIMIT 20",array($desdeSql,$hastaSql),'ss');
$topIndicadores=consultaVarias($conexion,"SELECT COALESCE(NULLIF(d.descripcion,''),NULLIF(d.concepto,''),d.codigo) item,SUM(d.cantidad) cantidad FROM pedidos p JOIN pedidos_detalle d ON d.pedido_id=p.pedido_id WHERE p.estado<>'ANULADO' AND p.fecha_creacion BETWEEN ? AND ? AND d.modulo='SENALIZACION' AND (d.concepto LIKE '%Indicador%' OR d.descripcion LIKE '%indicador%') GROUP BY COALESCE(NULLIF(d.descripcion,''),NULLIF(d.concepto,''),d.codigo) ORDER BY cantidad DESC LIMIT 20",array($desdeSql,$hastaSql),'ss');

$clienteId=(int)($_GET['cliente_id']??0); $clienteFicha=$clienteId>0?comercialCliente($conexion,$clienteId):null;
$clienteSeg=array();$clienteOps=array();$clienteStats=array();$clienteDocs=array();$clientePrefs=array();$clienteEspecificaciones=array();$clienteEspecificacionesHistoricas=array();
if($clienteFicha){
    $clienteEspecificaciones=especificacionesTecnicasCliente($conexion,$clienteId,true);
    $clienteEspecificacionesHistoricas=especificacionesTecnicasCliente($conexion,$clienteId,false);
    $clienteSeg=consultaVarias($conexion,"SELECT * FROM comercial_seguimientos WHERE cliente_id=? ORDER BY fecha_creacion DESC LIMIT 100",array($clienteId),'i');
    $clienteOps=consultaVarias($conexion,"SELECT * FROM comercial_oportunidades WHERE cliente_id=? ORDER BY fecha_creacion DESC LIMIT 100",array($clienteId),'i');
    $clienteStats=consultaUna($conexion,"SELECT (SELECT COUNT(*) FROM cotizaciones WHERE cliente_id=? AND cotizacion_numero IS NOT NULL AND estado<>'ANULADA') cotizaciones,(SELECT COUNT(*) FROM pedidos WHERE cliente_id=? AND pedido_numero IS NOT NULL AND estado<>'ANULADO') pedidos,(SELECT COUNT(*) FROM cotizaciones c WHERE c.cliente_id=? AND c.cotizacion_numero IS NOT NULL AND c.estado<>'ANULADA' AND EXISTS(SELECT 1 FROM pedidos p WHERE p.cotizacion_id=c.cotizacion_id AND p.estado<>'ANULADO')) convertidas,(SELECT COALESCE(SUM(total),0) FROM pedidos WHERE cliente_id=? AND pedido_numero IS NOT NULL AND estado<>'ANULADO') total_pedidos,(SELECT MAX(fecha_creacion) FROM pedidos WHERE cliente_id=? AND estado<>'ANULADO') ultimo_pedido",array($clienteId,$clienteId,$clienteId,$clienteId,$clienteId),'iiiii');
    $clienteDocs=consultaVarias($conexion,"(SELECT 'COTIZACION' tipo,cotizacion_id id,cotizacion_numero numero,fecha_creacion fecha,total,estado FROM cotizaciones WHERE cliente_id=? AND cotizacion_numero IS NOT NULL) UNION ALL (SELECT 'PEDIDO',pedido_id,pedido_numero,fecha_creacion,total,estado FROM pedidos WHERE cliente_id=? AND pedido_numero IS NOT NULL) ORDER BY fecha DESC LIMIT 40",array($clienteId,$clienteId),'ii');
    $prefControl=consultaVarias($conexion,"SELECT d.descripcion,SUM(d.cantidad) cantidad FROM pedidos p JOIN pedidos_detalle d ON d.pedido_id=p.pedido_id WHERE p.cliente_id=? AND p.estado<>'ANULADO' AND d.modulo='CONTROL' AND d.concepto='Base' GROUP BY d.descripcion ORDER BY cantidad DESC LIMIT 20",array($clienteId),'i');
    $prefPuls=consultaVarias($conexion,"SELECT d.descripcion,SUM(d.cantidad) cantidad FROM pedidos p JOIN pedidos_detalle d ON d.pedido_id=p.pedido_id WHERE p.cliente_id=? AND p.estado<>'ANULADO' AND d.modulo='SENALIZACION' AND (d.concepto LIKE '%Botonera%' OR d.concepto LIKE '%Pulsador%') GROUP BY d.descripcion ORDER BY cantidad DESC LIMIT 20",array($clienteId),'i');
    $aggC=array();foreach($prefControl as $x){$m=comercialExtraerModeloControl((string)$x['descripcion']);$aggC[$m]=($aggC[$m]??0)+(float)$x['cantidad'];}arsort($aggC);
    $aggP=array();foreach($prefPuls as $x){$m=comercialExtraerModeloPulsador((string)$x['descripcion']);$aggP[$m]=($aggP[$m]??0)+(float)$x['cantidad'];}arsort($aggP);
    $clientePrefs=array('control'=>array_key_first($aggC)?:'—','pulsador'=>array_key_first($aggP)?:'—');
}

function nombreMes(string $ym): string { $a=explode('-',$ym);$n=(int)($a[1]??0);$meses=array(1=>'Ene',2=>'Feb',3=>'Mar',4=>'Abr',5=>'May',6=>'Jun',7=>'Jul',8=>'Ago',9=>'Sep',10=>'Oct',11=>'Nov',12=>'Dic'); return ($meses[$n]??$ym).' '.($a[0]??''); }
