color:var(--muted);margin-bottom:4px}.event p{margin:0;white-space:pre-wrap}.contact-card{display:grid;grid-template-columns:1fr auto;gap:10px;padding:10px;border-bottom:1px solid #edf1f3}.contact-card:last-child{border-bottom:0}.contact-card strong{display:block}.empty{padding:22px;text-align:center;color:var(--muted);border:1px dashed #cbd8df;border-radius:9px}.two-col-client{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(320px,.7fr);gap:14px}
