<div class="kpis"><div class="kpi"><small>Cotizaciones emitidas</small><strong><?=number_format((int)($kpiCot['cantidad']??0),0,',','.')?></strong><span><?=comercialMoneda($kpiCot['total']??0)?></span></div><div class="kpi"><small>Conversión real</small><strong><?=number_format($conversion,1,',','.')?>%</strong><span><?=(int)($kpiCohorte['convertidas']??0)?> de <?=(int)($kpiCohorte['cotizaciones']??0)?> cotizaciones</span></div><div class="kpi"><small>C → #</small><strong><?=number_format($conversionC,1,',','.')?>%</strong><span><?=(int)($kpiCohorteC['convertidas']??0)?> obras convertidas</span></div><div class="kpi"><small>R → P</small><strong><?=number_format($conversionR,1,',','.')?>%</strong><span><?=(int)($kpiCohorteR['convertidas']??0)?> pedidos convertidos</span></div><div class="kpi"><small>Importe convertido</small><strong style="font-size:18px"><?=comercialMoneda($kpiCohorte['importe_convertido']??0)?></strong><span>de <?=comercialMoneda($kpiCohorte['importe_cotizado']??0)?></span></div><div class="kpi"><small>Ticket promedio pedido</small><strong style="font-size:18px"><?=comercialMoneda($ticketPedido)?></strong><span><?=number_format((int)($kpiPed['cantidad']??0),0,',','.')?> pedidos del período</span></div><div class="kpi"><small>Tiempo de conversión</small><strong><?=number_format((float)($kpiCohorte['dias_promedio']??0),1,',','.')?> d</strong><span>Mediana <?=number_format($medianaConversion,1,',','.')?> días</span></div><div class="kpi"><small>Pedidos directos</small><strong><?=number_format((int)($kpiDirectos['total']??0),0,',','.')?></strong><span># <?=(int)($kpiDirectos['obras']??0)?> · P. <?=(int)($kpiDirectos['suministros']??0)?></span></div><div class="kpi"><small>Equipos</small><strong><?=number_format((float)($equiposPeriodo['equipos']??0),0,',','.')?></strong><span>Controles pedidos</span></div><div class="kpi"><small>Seguimientos vencidos/hoy</small><strong><?=number_format((int)($pendientesHoy['cantidad']??0),0,',','.')?></strong><span>Requieren atención</span></div><div class="kpi"><small>Pipeline bruto</small><strong style="font-size:18px"><?=comercialMoneda($oportunidadesAbiertas['importe']??0)?></strong><span><?=(int)($oportunidadesAbiertas['cantidad']??0)?> oportunidades</span></div><div class="kpi"><small>Pipeline ponderado</small><strong style="font-size:18px"><?=comercialMoneda($pipelinePonderado)?></strong><span>Según probabilidades de mantenimiento</span></div></div>
<section class="panel"><h2>Comparación con período anterior</h2><div class="sub">Ventana anterior equivalente: <?=comercialEsc($periodoAnteriorEtiqueta)?>. La conversión compara cohortes de cotizaciones; pedidos y facturación comparan documentos emitidos en cada período.</div><div class="comparison">
<?php $clase=function($v){return $v>0?'up':($v<0?'down':'flat');}; $signo=function($v){return $v>0?'+':'';}; ?>
<div class="compare-item"><small>Conversión</small><strong><?=number_format($conversion,1,',','.')?>%</strong><span class="delta <?=$clase($deltaConversion)?>"><?=$signo($deltaConversion).number_format($deltaConversion,1,',','.')?> p.p.</span></div>
<div class="compare-item"><small>Cotizaciones</small><strong><?=(int)($kpiCot['cantidad']??0)?></strong><span class="delta <?=$clase($deltaCotizaciones)?>"><?=$signo($deltaCotizaciones).number_format($deltaCotizaciones,0,',','.')?> vs anterior</span></div>
<div class="compare-item"><small>Pedidos</small><strong><?=(int)($kpiPed['cantidad']??0)?></strong><span class="delta <?=$clase($deltaPedidos)?>"><?=$signo($deltaPedidos).number_format($deltaPedidos,0,',','.')?> vs anterior</span></div>
<div class="compare-item"><small>Importe pedidos</small><strong style="font-size:15px"><?=comercialMoneda($kpiPed['total']??0)?></strong><span class="delta <?=$clase($deltaImportePedidos)?>"><?=$signo($deltaImportePedidos).comercialMoneda(abs($deltaImportePedidos))?> vs anterior</span></div>
<div class="compare-item"><small>Ticket promedio</small><strong style="font-size:15px"><?=comercialMoneda($ticketPedido)?></strong><span class="delta <?=$clase($deltaTicket)?>"><?=$signo($deltaTicket).comercialMoneda(abs($deltaTicket))?> vs anterior</span></div>
</div></section>
<section class="panel"><h2>Pipeline ponderado por etapa</h2><div class="sub">El importe ponderado aplica la probabilidad configurada en Mantenimiento a cada oportunidad abierta.</div><?php if(!$pipelineFilas):?><div class="empty">No hay oportunidades abiertas.</div><?php else:foreach($pipelineFilas as $pf):$prob=(float)($probabilidades[$pf['estado']]??0);$pond=(float)$pf['importe']*$prob/100;?><div class="pipeline-stage"><strong><?=comercialEsc(str_replace('_',' ',$pf['estado']))?></strong><span><?=$prob?>%</span><span><?=comercialMoneda($pf['importe'])?></span><b><?=comercialMoneda($pond)?></b></div><?php endforeach;endif;?></section>
<div class="grid2"><section class="panel"><h2>Próximos seguimientos</h2><div class="sub">Pendientes ordenados por fecha de próximo contacto.</div><?php if(!$seguimientosPendientes):?><div class="empty">No hay seguimientos pendientes.</div><?php else:?><div class="tablewrap"><table><tr><th>Cliente</th><th>Tipo</th><th>Próximo</th><th>Anotación</th></tr><?php foreach(array_slice($seguimientosPendientes,0,12) as $s):?><tr><td><a class="client" href="comercial.php?tab=cliente&cliente_id=<?=(int)$s['cliente_id']?>"><?=comercialEsc($s['clientes_nomfantasia'])?></a><span class="code"><?=comercialEsc($s['clientes_codigo'])?></span></td><td><span class="pill"><?=comercialEsc($s['tipo'])?></span></td><td><?=comercialFecha($s['proximo_contacto'],true)?></td><td><?=comercialEsc(mb_strimwidth($s['nota'],0,80,'…'))?></td></tr><?php endforeach;?></table></div><?php endif;?></section><section class="panel"><h2>Oportunidades abiertas</h2><div class="sub">Pipeline comercial actual.</div><?php if(!$oportunidades):?><div class="empty">Todavía no hay oportunidades.</div><?php else:?><div class="tablewrap"><table><tr><th>Cliente</th><th>Oportunidad</th><th>Responsable</th><th>Próximo contacto</th><th>Estado</th><th>Equipos</th><th>Estimado</th></tr><?php foreach(array_slice(array_filter($oportunidades, function($o){ return !in_array($o['estado'],array('GANADA','PERDIDA'),true); }),0,12) as $o):?><tr><td><a class="client" href="comercial.php?tab=cliente&cliente_id=<?=(int)$o['cliente_id']?>"><?=comercialEsc($o['clientes_nomfantasia'])?></a></td><td><?=comercialEsc($o['titulo'])?></td><td><?=comercialEsc($o['responsable_nombre']?:'—')?></td><td><?=comercialFecha($o['proximo_contacto'],true)?></td><td><span class="pill"><?=comercialEsc(str_replace('_',' ',$o['estado']))?></span></td><td><?=number_format((int)$o['equipos_estimados'],0,',','.')?></td><td><?=comercialMoneda($o['importe_estimado'])?></td></tr><?php endforeach;?></table></div><?php endif;?></section></div>
<section class="panel"><h2>Clientes con mayor cantidad de equipos</h2><div class="sub">Conversión por cohorte real de cotizaciones del período; los pedidos directos no inflan la tasa.</div><div class="tablewrap"><table><tr><th>Cliente</th><th>Cotizaciones</th><th>Convertidas</th><th>Conversión</th><th>Pedidos período</th><th>Equipos</th><th>Último pedido</th><th></th></tr><?php foreach(array_slice($ranking,0,20) as $r):$conv=(int)$r['cotizaciones']>0?((int)$r['convertidas']/(int)$r['cotizaciones']*100):0;?><tr><td><span class="client"><?=comercialEsc($r['clientes_nomfantasia'])?></span><span class="code"><?=comercialEsc($r['clientes_codigo'])?></span></td><td><?=number_format((int)$r['cotizaciones'],0,',','.')?></td><td><?=number_format((int)$r['convertidas'],0,',','.')?></td><td><?=number_format($conv,1,',','.')?>%</td><td><?=number_format((int)$r['pedidos'],0,',','.')?></td><td><strong><?=number_format((float)$r['equipos'],0,',','.')?></strong></td><td><?=comercialFecha($r['ultimo_pedido'])?></td><td><a class="mini" href="comercial.php?tab=cliente&cliente_id=<?=(int)$r['clientes_id']?>">Ficha</a></td></tr><?php endforeach;?></table></div></section>
<?php endif; ?>

